   $ex${"titre":"Tourisme : des lieux qui vivent et des lieux qui souffrent","competence":"analyser-document","situation":"Noa prépare un exposé sur le tourisme en France. Il place quelques lieux sur une carte et lit le reportage, écrit pour l’exercice, d’une station balnéaire imaginée.","documents":[{"id":"carte","type":"carte","titre":"Quatre types de tourisme","fond":"france","lieux":[{"id":"z1","lieu":"paris","symbole":"carre","teinte":"bleu","nom":"Paris"},{"id":"z2","lon":1.52,"lat":47.62,"symbole":"carre","teinte":"bleu","nom":"Chambord"},{"id":"z3","lon":-2.39,"lat":47.29,"symbole":"triangle","teinte":"ambre","nom":"La Baule"},{"id":"z4","lieu":"nice","symbole":"triangle","teinte":"ambre","nom":"Nice"},{"id":"z5","lon":6.87,"lat":45.92,"symbole":"etoile","teinte":"violet","nom":"Chamonix"},{"id":"z6","lon":6.98,"lat":45.45,"symbole":"etoile","teinte":"violet","nom":"Val d’Isère"}],"legende":[{"teinte":"bleu","texte":"Urbain et culturel"},{"teinte":"ambre","texte":"Balnéaire"},{"teinte":"violet","texte":"De montagne"}]},{"id":"reportage","type":"texte","genre":"article","titre":"Reportage à Anse-du-Levant","auteur":"Texte écrit pour l’exercice (station imaginée).","blocs":["Anse-du-Levant compte 400 habitants toute l’année, mais 9 000 personnes en août. Au fil des années, les immeubles ont bétonné la côte.","Les emplois y sont surtout saisonniers : cafés, hôtels et locations ferment presque tous dès octobre."]}],"questions":[{"enonce":"Touche **les deux** lieux de tourisme de montagne de la carte.","aide":"Quel symbole marque les lieux « de montagne » dans la légende ?","type":"zone","document":"carte","multiple":true},{"enonce":"Touche le mot qui dit que la côte a été couverte de constructions.","aide":"Le béton est le matériau des immeubles.","type":"zone","document":"reportage","multiple":false},{"enonce":"Le tourisme pèse près de 8 % du PIB. Si le PIB français est de 2 500 milliards d’euros (valeur arrondie pour l’exercice), combien le tourisme représente-t-il ? Réponds en milliards.","aide":"8 % de 2 500 : 2 500 × 8 ÷ 100.","type":"nombre","unite":"milliards"},{"enonce":"Quel problème le reportage met-il en évidence ?","aide":"Relis chaque paragraphe : ce sont les deux limites du tourisme.","type":"choix","options":[{"id":"a","texte":"Un territoire sans aucune construction"},{"id":"b","texte":"Des emplois stables et à l’année pour tous"},{"id":"c","texte":"Des emplois souvent saisonniers et une côte bétonnée"},{"id":"d","texte":"Un manque total de touristes en août"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5","z6"]},"explication":"**Chamonix** et **Val d’Isère**, dans les Alpes, illustrent le tourisme de montagne. La Baule et Nice sont balnéaires ; Paris et Chambord, urbains et culturels."},{"cle":{"type":"zone","ids":["m20"]},"explication":"Le **bétonnage** des littoraux est l’un des revers des aménagements touristiques : les stations recouvrent la côte d’immeubles."},{"cle":{"type":"nombre","valeur":200,"tolerance":5},"affichage":"200 milliards","explication":"2 500 × 8 ÷ 100 = **200 milliards d’euros** : le tourisme fait vivre des territoires entiers."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le tourisme a un **revers** : le bétonnage du littoral et des emplois **saisonniers**, précaires. Il fait vivre un territoire tout en menaçant ce qui le rend attirant."}]$ex$::jsonb),
