   $ex${"titre":"Les Françaises deviennent électrices","competence":"analyser-texte","situation":"En 1944, un texte de loi donne le droit de vote aux Françaises. Élise compare ce texte à la situation dans d’autres pays.","documents":[{"id":"texte","type":"texte","genre":"source","titre":"L’ordonnance du 21 avril 1944","auteur":"D’après l’ordonnance du 21 avril 1944 — texte adapté.","blocs":["Le gouvernement provisoire de la République française décide que les femmes sont électrices et éligibles dans les mêmes conditions que les hommes.","Elles pourront voter dès les prochaines élections organisées après la Libération."]},{"id":"pays","type":"tableau","titre":"Premier droit de vote national des femmes","source":"Dates arrondies au niveau national, d’après des repères historiques.","colonnes":["Pays","Année"],"lignes":[["Nouvelle-Zélande","1893"],["Allemagne","1918"],["États-Unis","1920"],["France","1944"],["Suisse","1971"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne les personnes à qui l’ordonnance accorde le droit de vote.","aide":"Relis la première phrase du texte.","type":"zone","document":"texte","multiple":false},{"enonce":"Touche le pays du tableau où les femmes ont voté **en dernier**.","aide":"Cherche l’année la plus récente.","type":"zone","document":"pays","multiple":false},{"enonce":"Combien d’années séparent le vote des Allemandes (1918) de celui des Françaises (1944) ?","aide":"Soustrais 1918 à 1944.","type":"nombre","unite":"ans"},{"enonce":"Quel événement permet à cette réforme d’aboutir en 1944 ?","aide":"Regarde la date de l’ordonnance : avril 1944.","type":"choix","options":[{"id":"a","texte":"La guerre d’Algérie et la fin de l’Empire colonial"},{"id":"b","texte":"Les grandes grèves et les manifestations de Mai 1968"},{"id":"c","texte":"La Libération et la refondation de la République"},{"id":"d","texte":"La chute du mur de Berlin et la fin du communisme"}],"multiple":false}]}$ex$::jsonb,
