  ('d47a1340-11ae-5fcc-8d34-f0b41d7e2e36'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Du programme des « Jours heureux » aux réformes","competence":"argumenter","situation":"Théo compare les demandes du Conseil national de la Résistance (mars 1944) avec ce que la République a réellement fait entre 1944 et 1946.","documents":[{"id":"cnr","type":"texte","genre":"source","titre":"Les demandes du programme du CNR (mars 1944)","auteur":"Extrait très adapté, en langage d’aujourd’hui.","blocs":["Le programme réclame un plan complet de sécurité sociale, pour garantir à tous des moyens d’existence quand ils ne peuvent plus travailler.","Il demande aussi le retour à la nation des grands moyens de production : charbon, électricité, gaz.","Enfin, il veut permettre aux enfants doués de poursuivre leurs études, quelle que soit la fortune de leurs parents."]},{"id":"realisations","type":"tableau","titre":"Ce qui a été réalisé","source":"Repères de cours.","colonnes":["Date","Réforme"],"lignes":[["1944","Droit de vote des femmes"],["Octobre 1945","Ordonnances créant la Sécurité sociale"],["1945-1946","Nationalisations (Renault, charbonnages, EDF-GDF…)"],["Octobre 1946","Préambule de la Constitution : droit à l’instruction"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui correspond aux **nationalisations** : les entreprises reviennent à la…","aide":"Une nationalisation rend une entreprise à la communauté.","type":"zone","document":"cnr","multiple":false},{"enonce":"Associe chaque demande du programme à sa réalisation.","aide":"Cherche, dans le tableau, la ligne qui reprend chaque idée.","type":"association","gauche":[{"id":"g0","texte":"Un plan complet de sécurité sociale"},{"id":"g1","texte":"Le retour à la nation des grands moyens de production"},{"id":"g2","texte":"Des études ouvertes à tous, quelle que soit la fortune"}],"droite":[{"id":"d0","texte":"Le droit à l’instruction dans le préambule de 1946"},{"id":"d1","texte":"Les nationalisations de 1945-1946"},{"id":"d2","texte":"Les ordonnances d’octobre 1945"}]},{"enonce":"Complète le cœur de ce modèle social.","aide":"Le cours parle d’une protection contre les risques de l’existence.","type":"trous","segments":["Les réformes de 1944-1946 protègent chacun par la ",0," nationale plutôt que par la ",1,"."],"banque":["solidarité","charité","concurrence","guerre"]},{"enonce":"Pourquoi dit-on que ces réformes forment un « socle » ?","aide":"La Sécurité sociale existe encore aujourd’hui.","type":"choix","options":[{"id":"a","texte":"Parce que la IVe République a duré vingt ans"},{"id":"b","texte":"Parce qu’elles ont été supprimées en 1958"},{"id":"c","texte":"Parce qu’elles ne concernent que les entreprises"},{"id":"d","texte":"Parce que le modèle social français en est encore l’héritier"}],"multiple":false}]}$ex$::jsonb,
