   $ex${"titre":"Le prix du sang","competence":"lire-tableau","situation":"Dans son manuel, Inès trouve un tableau qui compte les soldats morts dans cinq pays. Elle veut comprendre ce que dit ce bilan de la guerre totale.","documents":[{"id":"morts","type":"tableau","titre":"Soldats morts pendant la guerre (estimations arrondies)","source":"Ordres de grandeur arrondis, en millions d’hommes. Les historiens donnent des fourchettes.","colonnes":["Pays","Camp","Morts (millions)"],"lignes":[["France","Entente","1,4"],["Russie","Entente","1,8"],["Royaume-Uni","Entente","0,9"],["Allemagne","Empires centraux","2,0"],["Autriche-Hongrie","Empires centraux","1,1"]],"enteteLignes":true}],"questions":[{"enonce":"Touche **les deux pays** qui appartiennent aux Empires centraux.","aide":"Regarde la colonne « Camp ».","type":"zone","document":"morts","multiple":true},{"enonce":"Additionne les morts des trois pays de l’Entente du tableau. Réponds en millions.","aide":"Calcule 1,4 + 1,8 + 0,9.","type":"nombre","unite":"millions"},{"enonce":"Que montre ce tableau sur la nature de cette guerre ?","aide":"Regarde l’ordre de grandeur de chaque nombre : ce sont des millions.","type":"choix","options":[{"id":"a","texte":"Elle a fait peu de victimes car elle a été très courte et limitée"},{"id":"b","texte":"Elle a surtout tué des civils, et presque aucun soldat sur le front"},{"id":"c","texte":"Elle a mobilisé des armées de masse et fait des millions de morts"},{"id":"d","texte":"Elle n’a touché que la France et l’Allemagne, sans autre pays"}],"multiple":false}]}$ex$::jsonb,
