  ('6583dbde-d239-5bcb-a891-6ab8836842bd'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Lettre du front, affiche de l’arrière","competence":"analyser-document","situation":"Une lettre de poilu et une affiche de l’arrière : deux documents pour comprendre pourquoi on parle de « guerre totale ».","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un soldat, automne 1916","source":"Texte écrit pour l’exercice, inspiré des lettres de poilus.","blocs":["Chère Jeanne, nous sommes toujours près de Verdun. Il pleut sans cesse et la boue nous monte jusqu’aux genoux. La nuit, les rats passent sur nos couvertures et les poux ne nous laissent aucun repos.","Les obus tombent chaque jour sur la tranchée. Dans les journaux qu’on nous envoie, tout paraît facile, mais ici nous savons bien que ce n’est pas vrai. Je ne peux pas tout écrire : le courrier est ouvert par la censure.","Embrasse les enfants pour moi. Dis-leur que leur père pense à eux. Ton Louis."]},{"id":"affiche","type":"fiche","modele":"affiche","entete":"Souscrivez à l’emprunt national !","sousTitre":"Affiche écrite pour l’exercice","emoji":"🪙","lignes":[{"texte":"Chaque pièce d’or que vous donnez aide nos soldats.","id":"z1"},{"texte":"Échangez votre or contre des titres de l’emprunt.","id":"z2"}],"pied":"Pour la patrie, pour la victoire","teinte":"bleu"}],"questions":[{"enonce":"Touche **les trois mots** de la lettre qui décrivent les conditions de vie dans la tranchée.","aide":"Cherche ce qui est sale, humide ou nuisible.","type":"zone","document":"lettre","multiple":true},{"enonce":"À quel domaine de la guerre totale l’affiche correspond-elle ?","aide":"L’affiche demande de l’argent et de l’or.","type":"choix","options":[{"id":"a","texte":"Le domaine économique : on finance la guerre"},{"id":"b","texte":"Le domaine militaire : on recrute des soldats"},{"id":"c","texte":"Le domaine moral : on censure le courrier"},{"id":"d","texte":"Le domaine scientifique : on invente des armes"}],"multiple":false},{"enonce":"Pourquoi Louis écrit-il « je ne peux pas tout écrire » ?","aide":"Relis la fin du deuxième paragraphe.","type":"choix","options":[{"id":"a","texte":"Parce que la censure ouvre le courrier"},{"id":"b","texte":"Parce que les obus détruisent les lettres"},{"id":"c","texte":"Parce qu’il n’a plus de papier"},{"id":"d","texte":"Parce qu’il ne sait pas écrire longuement"}],"multiple":false},{"enonce":"Range ces exemples selon le domaine de la guerre totale qu’ils illustrent.","aide":"La guerre totale mobilise l’économie, la science et les esprits.","type":"categories","categories":[{"id":"c0","texte":"Domaine économique"},{"id":"c1","texte":"Domaine scientifique"},{"id":"c2","texte":"Domaine moral"}],"items":[{"id":"i0","texte":"Les gaz de combat et les chars apparaissent"},{"id":"i1","texte":"L’aviation et les sous-marins"},{"id":"i2","texte":"Le « bourrage de crâne » dans les journaux"},{"id":"i3","texte":"Les emprunts de guerre"},{"id":"i4","texte":"Les femmes remplacent les hommes à l’usine"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14","m23","m30"]},"explication":"**Boue, rats, poux** : voilà le quotidien des soldats dans les tranchées, loin des récits des journaux."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’affiche demande de financer la guerre par un **emprunt de guerre** : c’est la mobilisation **économique** des civils."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le courrier des soldats est lu par la **censure** : elle fait partie du contrôle moral de l’opinion, comme la propagande et le « bourrage de crâne »."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c2","i3":"c0","i4":"c0"}},"explication":"Usines et emprunts relèvent de l’**économie** ; gaz, chars, avions et sous-marins de la **science** ; bourrage de crâne et censure du **moral**."}]$ex$::jsonb),
