   $ex${"titre":"Vers une Europe plus autonome","competence":"raisonner","situation":"Un article écrit pour l’exercice et un tableau montrent pourquoi l’Union cherche plus d’autonomie.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Dépendances et autonomie","source":"Article écrit pour l’exercice.","blocs":["Depuis 2022, l’invasion de l’Ukraine par la Russie a montré les limites de l’Union : elle dépendait du gaz russe pour une part de son énergie.","L’Union veut donc gagner en autonomie dans plusieurs domaines stratégiques. Elle garde pourtant une influence forte grâce à ses normes et à son marché unique."]},{"id":"domaines","type":"tableau","titre":"Quatre domaines stratégiques","colonnes":["Domaine","Exemple de dépendance"],"lignes":[["Énergie","Importation de gaz"],["Santé","Production de vaccins"],["Numérique","Semi-conducteurs"],["Sécurité","Armement"]],"enteteLignes":true}],"questions":[{"enonce":"Touche **le mot** qui désigne l’objectif de l’Union après 2022.","aide":"C’est la capacité d’agir seul.","type":"zone","document":"article","multiple":false},{"enonce":"Associe chaque domaine à son exemple de dépendance.","aide":"Relis le tableau.","type":"association","gauche":[{"id":"g0","texte":"Énergie"},{"id":"g1","texte":"Santé"},{"id":"g2","texte":"Numérique"},{"id":"g3","texte":"Sécurité"}],"droite":[{"id":"d0","texte":"Armement"},{"id":"d1","texte":"Importation de gaz"},{"id":"d2","texte":"Semi-conducteurs"},{"id":"d3","texte":"Production de vaccins"}]},{"enonce":"L’Union européenne dispose-t-elle d’une armée commune ?","aide":"Rappelle-toi la faiblesse politique de l’Union.","type":"choix","options":[{"id":"a","texte":"Oui, mais uniquement en mer et pour des missions de paix"},{"id":"b","texte":"Non, elle n’a aucune défense et aucune alliance militaire"},{"id":"c","texte":"Oui, une armée européenne unique placée sous un seul chef"},{"id":"d","texte":"Non, sa défense repose sur l’OTAN et les armées nationales"}],"multiple":false},{"