  ('e0803bfa-c2f5-5ae6-bfdc-284d5e9dbbee'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre de Dakar","competence":"analyser-texte","situation":"Pour comprendre la décolonisation de l’intérieur, Malik lit une lettre imaginaire écrite en 1960 par un instituteur sénégalais à une amie française.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Dakar, 1960","source":"Lettre écrite pour l’exercice.","blocs":["Dakar, le 20 août 1960","Chère Marie, en 1944, mon père a combattu dans l’armée française pour libérer l’Europe. À son retour, il a répété que l’Afrique avait payé sa part de la victoire et qu’elle attendait autre chose que des remerciements.","Aujourd’hui, le drapeau change, et aucune bataille n’a eu lieu : tout a été discuté à la table des négociations. Mais tout n’est pas réglé. Notre arachide part presque toute à l’étranger, et nous devons acheter à l’extérieur ce que nos usines ne fabriquent pas encore. L’indépendance est une porte qui s’ouvre, pas une maison construite."]}],"questions":[{"enonce":"Touche le mot qui rappelle que les colonies ont participé à la victoire de 1945.","aide":"Cherche ce que le père a fait pendant la guerre.","type":"zone","document":"lettre","multiple":false},{"enonce":"Quelle cause de la décolonisation le père invoque-t-il dans sa lettre ?","aide":"Relis la phrase sur l’armée française en 1944.","type":"choix","options":[{"id":"a","texte":"L’hostilité des deux Grands aux empires"},{"id":"b","texte":"La Charte de l’ONU"},{"id":"c","texte":"La participation des colonies à la victoire"},{"id":"d","texte":"L’affaiblissement des puissances coloniales"}],"multiple":false},{"enonce":"Touche le mot qui montre que l’économie reste dépendante de l’extérieur.","aide":"Quel produit « part presque tout à l’étranger » ?","type":"zone","document":"lettre","multiple":false},{"enonce":"Complète la conclusion de la lettre.","aide":"L’auteur dit que l’indépendance est « une porte qui s’ouvre, pas une maison construite ».","type":"trous","segments":["L’indépendance ",0," ne suffit pas : l’économie reste ",1," des anciennes puissances."],"banque":["dépendante","politique","militaire","indépendante"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12"]},"explication":"Le père a **combattu** dans l’armée française : les colonies réclament une contrepartie à leur effort de guerre."},{"cle":{"type":"choix","ids":["c"]},"explication":"Il rappelle l’effort de guerre des colonies : c’est la **participation à la victoire**, qui nourrit les revendications."},{"cle":{"type":"zone","ids":["m73"]},"explication":"L’**arachide** est exportée presque brute : l’économie dépend toujours de l’extérieur."},{"cle":{"type":"trous","trous":[["politique"],["dependante"]]},"affichage":"politique · dépendante","explication":"L’indépendance **politique** ne suffit pas : l’économie reste **dépendante**, comme le dit la fin du cours."}]$ex$::jsonb),
