   $ex${"titre":"Mettre le charbon et l’acier en commun","competence":"analyser-texte","situation":"Samir lit un texte adapté de la déclaration du 9 mai 1950, puis repère qui décide quoi dans l’Europe d’aujourd’hui.","documents":[{"id":"texte","type":"texte","genre":"source","titre":"La déclaration du 9 mai 1950","source":"D’après la déclaration Schuman — texte très librement adapté pour l’exercice.","blocs":["Les pays d’Europe ne construiront pas leur union d’un seul coup. Ils avanceront par de petites réalisations concrètes, qui les rendront solidaires les uns des autres.","Pour commencer, on propose de placer toute la production de charbon et d’acier de la France et de l’Allemagne sous une autorité commune, ouverte aux autres pays d’Europe.","Ainsi, une guerre entre ces deux pays ne sera pas seulement impensable : elle deviendra matériellement impossible."]},{"id":"institutions","type":"tableau","titre":"Les institutions européennes","source":"D’après le cours.","colonnes":["Institution","Ce qui la caractérise"],"lignes":[["Commission","Propose les textes et veille à l’application des traités"],["Parlement européen","Élu au suffrage universel direct depuis 1979"],["Conseil de l’Union","Réunit les ministres des États"],["Conseil européen","Réunit les chefs d’État et de gouvernement"],["Cour de justice","Tranche les litiges"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux productions que le texte propose de mettre en commun.","aide":"Ce sont deux matières premières de l’industrie lourde.","type":"zone","document":"texte","multiple":true},{"enonce":"Quelle méthode le début du texte recommande-t-il pour construire l’Europe ?","aide":"Relis la première phrase du texte.","type":"choix","options":[{"id":"a","texte":"Avancer par de petites réalisations concrètes"},{"id":"b","texte":"Créer tout de suite un seul État européen"},{"id":"c","texte":"Attendre que les peuples le réclament"},{"id":"d","texte":"Signer un traité militaire unique"}],"multiple":false},{"enonce":"Touche l’institution qui propose les textes européens.","aide":"Cherche « propose les textes » dans la colonne de droite.","type":"zone","document":"institutions","multiple":false},{"enonce":"Range chaque institution selon sa logique : supranationale (ses décisions s’imposent aux États) ou intergouvernementale (les États décident ensemble).","aide":"Qui compose l’institution : des représentants des États, ou un organe qui s’impose à eux ?","type":"categories","categories":[{"id":"c0","texte":"Supranationale"},{"id":"c1","texte":"Intergouvernementale"}],"items":[{"id":"i0","texte":"Cour de justice"},{"id":"i1","texte":"Conseil européen"},{"id":"i2","texte":"Conseil de l’Union"},{"id":"i3","texte":"Commission"}]}]}$ex$::jsonb,
