   $ex${"titre":"Un veto qui bloque le monde","competence":"argumenter","situation":"Le Conseil de sécurité adopte une résolution avec au moins 9 voix « pour » et aucun veto d’un des cinq membres permanents. Mina lit un article imaginaire et un vote fictif.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Cyberattaque : l’ONU divisée","source":"Article imaginaire, écrit pour l’exercice.","blocs":["Dans la nuit du 12 mars, une cyberattaque paralyse les hôpitaux de trois pays voisins. Les pirates n’ont pas de frontières : on ignore même d’où ils frappent.","Le lendemain, le Conseil de sécurité de l’ONU examine un projet de résolution. Un de ses membres permanents annonce qu’il utilisera son veto. Chaque État promet de protéger ses propres réseaux, en ordre dispersé."]},{"id":"vote","type":"tableau","titre":"Le vote fictif au Conseil de sécurité","source":"Chiffres imaginaires, écrits pour l’exercice.","colonnes":["Vote","Voix"],"lignes":[["Pour","13"],["Contre (un membre permanent)","1"],["Abstention","1"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne le pouvoir de bloquer la résolution.","aide":"Cherche le droit réservé aux cinq membres permanents.","type":"zone","document":"article","multiple":false},{"enonce":"De combien de voix « pour » le vote dépasse-t-il le minimum de 9 voix requis ?","aide":"Lis le nombre de « pour » dans le tableau, puis soustrais 9.","type":"nombre","unite":"voix"},{"enonce":"La résolution est-elle adoptée ?","aide":"Relis la règle donnée au début de l’exercice : deux conditions.","type":"choix","options":[{"id":"a","texte":"Oui : 13 voix dépassent largement le minimum de 9 voix requis"},{"id":"b","texte":"Oui : le veto n’est qu’un simple avis que la majorité peut ignorer"},{"id":"c","texte":"Non : il manque encore 2 voix pour atteindre les 15 voix"},{"id":"d","texte":"Non : le veto d’un membre permanent la bloque malgré 13 voix"}],"multiple":false},{"enonce":"Et si ce membre permanent s’était abstenu au lieu de voter contre ?","aide":"Une abstention est-elle un veto ?","type":"choix","options":[{"id":"a","texte":"Elle aurait été rejetée quand même"},{"id":"b","texte":"Le vote aurait été annulé"},{"id":"c","texte":"La résolution aurait été adoptée"},{"id":"d","texte":"Il aurait fallu 15 voix pour"}],"multiple":false},{"enonce":"Complète la difficulté de la gouvernance mondiale.","aide":"La cyberattaque traverse les frontières ; les États, eux, protègent chacun leurs réseaux.","type":"trous","segments":["Les menaces sont ",0," alors que les décisions restent ",1,"."],"banque":["transnationales","locales","militaires","nationales"]}]}$ex$::jsonb,
